import { describe, expect, it } from "vitest";
import { isSameDay } from "../index.js";

describe("isSameDay regression", () => {
  it("returns true for different times on the same local calendar day", () => {
    expect(
      isSameDay(
        new Date(2024, 0, 15, 0, 0),
        new Date(2024, 0, 15, 23, 59),
      ),
    ).toBe(true);
  });

  it("keeps month distinctions for the same day of the month", () => {
    expect(
      isSameDay(new Date(2024, 0, 15, 12), new Date(2024, 1, 15, 12)),
    ).toBe(false);
  });

  it("keeps year distinctions for the same month and day", () => {
    expect(
      isSameDay(new Date(2024, 0, 15, 12), new Date(2025, 0, 15, 12)),
    ).toBe(false);
  });
});

