import { tz } from "@date-fns/tz";
import { describe, expect, it } from "vitest";
import { isSameDay } from "../index.js";

describe("isSameDay regressions", () => {
  it("returns true for different times on the same local calendar day", () => {
    expect(
      isSameDay(
        new Date(2024, 5, 7, 0, 1),
        new Date(2024, 5, 7, 23, 59),
      ),
    ).toBe(true);
  });

  it("preserves month, year, and day distinctions", () => {
    const date = new Date(2024, 5, 7, 12);

    expect(isSameDay(date, new Date(2024, 6, 7, 12))).toBe(false);
    expect(isSameDay(date, new Date(2025, 5, 7, 12))).toBe(false);
    expect(isSameDay(date, new Date(2024, 5, 8, 12))).toBe(false);
  });

  it("does not mutate its inputs", () => {
    const laterDate = new Date(2024, 5, 7, 12, 34, 56, 789);
    const earlierDate = new Date(2024, 5, 7, 23, 45, 6, 321);
    const laterTime = laterDate.getTime();
    const earlierTime = earlierDate.getTime();

    expect(isSameDay(laterDate, earlierDate)).toBe(true);
    expect(laterDate.getTime()).toBe(laterTime);
    expect(earlierDate.getTime()).toBe(earlierTime);
  });

  it("preserves invalid dates and context normalization", () => {
    expect(isSameDay(new Date(NaN), new Date(NaN))).toBe(false);
    expect(
      isSameDay("2024-04-10T07:00:00Z", "2024-04-10T15:00:00Z", {
        in: tz("America/Los_Angeles"),
      }),
    ).toBe(true);
  });
});

