+import { tz } from "@date-fns/tz";
+import { describe, expect, it } from "vitest";
+import { isSameDay } from "../index.js";
+
+describe("isSameDay regressions", () => {
+  it("treats different times on the same local day as equal without mutating inputs", () => {
+    const laterDate = new Date(2014, 8 /* Sep */, 4, 6, 0);
+    const earlierDate = new Date(2014, 8 /* Sep */, 4, 18, 0);
+    const laterTime = laterDate.getTime();
+    const earlierTime = earlierDate.getTime();
+
+    expect(isSameDay(laterDate, earlierDate)).toBe(true);
+    expect(laterDate.getTime()).toBe(laterTime);
+    expect(earlierDate.getTime()).toBe(earlierTime);
+  });
+
+  it("keeps day, month, and year distinctions", () => {
+    expect(
+      isSameDay(
+        new Date(2024, 8 /* Sep */, 4, 6),
+        new Date(2024, 8 /* Sep */, 5, 6),
+      ),
+    ).toBe(false);
+    expect(
+      isSameDay(
+        new Date(2024, 8 /* Sep */, 4, 6),
+        new Date(2024, 9 /* Oct */, 4, 6),
+      ),
+    ).toBe(false);
+    expect(
+      isSameDay(
+        new Date(2024, 8 /* Sep */, 4, 6),
+        new Date(2025, 8 /* Sep */, 4, 6),
+      ),
+    ).toBe(false);
+  });
+
+  it("returns false for invalid dates", () => {
+    expect(isSameDay(new Date(NaN), new Date(NaN))).toBe(false);
+    expect(isSameDay(new Date(2024, 8, 4), new Date(NaN))).toBe(false);
+  });
+
+  it("supports timestamp and string inputs in the requested timezone context", () => {
+    const context = tz("America/Los_Angeles");
+    expect(
+      isSameDay(
+        Date.parse("2024-04-10T07:00:00Z"),
+        "2024-04-10T15:00:00Z",
+        { in: context },
+      ),
+    ).toBe(true);
+    expect(
+      isSameDay(
+        Date.parse("2024-04-10T07:00:00Z"),
+        "2024-04-11T07:00:00Z",
+        { in: context },
+      ),
+    ).toBe(false);
+  });
+});
