import { describe, expect, it } from "vitest";
import { isSameDay } from "../index.js";

describe("isSameDay regressions", () => {
  it("matches different times on the same local calendar day", () => {
    expect(
      isSameDay(
        new Date(2024, 6, 15, 0, 1),
        new Date(2024, 6, 15, 23, 59),
      ),
    ).toBe(true);
  });

  it("keeps month and year distinctions for the same day of month", () => {
    expect(isSameDay(new Date(2024, 6, 15, 12), new Date(2024, 7, 15, 12))).toBe(
      false,
    );
    expect(isSameDay(new Date(2024, 6, 15, 12), new Date(2025, 6, 15, 12))).toBe(
      false,
    );
  });

  it("does not mutate the input dates while normalizing their times", () => {
    const laterDate = new Date(2024, 6, 15, 14, 30, 45, 123);
    const earlierDate = new Date(2024, 6, 15, 8, 15, 30, 456);
    const laterTimestamp = laterDate.getTime();
    const earlierTimestamp = earlierDate.getTime();

    expect(isSameDay(laterDate, earlierDate)).toBe(true);
    expect(laterDate.getTime()).toBe(laterTimestamp);
    expect(earlierDate.getTime()).toBe(earlierTimestamp);
  });
});

