import { tz } from "@date-fns/tz";
import { describe, expect, it } from "vitest";
import { isSameDay } from "../index.js";

describe("isSameDay regressions", () => {
  it("returns true for different times on the same local calendar day", () => {
    expect(
      isSameDay(
        new Date(2024, 5, 15, 0, 1),
        new Date(2024, 5, 15, 23, 59),
      ),
    ).toBe(true);
  });

  it("preserves month and year distinctions", () => {
    expect(
      isSameDay(new Date(2024, 5, 15, 12), new Date(2024, 6, 15, 12)),
    ).toBe(false);
    expect(
      isSameDay(new Date(2024, 5, 15, 12), new Date(2025, 5, 15, 12)),
    ).toBe(false);
  });

  it("does not mutate the input dates", () => {
    const laterDate = new Date(2024, 5, 15, 12, 34, 56, 789);
    const earlierDate = new Date(2024, 5, 15, 23, 45, 6, 123);
    const laterTimestamp = laterDate.getTime();
    const earlierTimestamp = earlierDate.getTime();

    expect(isSameDay(laterDate, earlierDate)).toBe(true);
    expect(laterDate.getTime()).toBe(laterTimestamp);
    expect(earlierDate.getTime()).toBe(earlierTimestamp);
  });

  it("keeps timestamp, string, and context normalization", () => {
    expect(
      isSameDay("2024-04-10T07:00:00Z", new Date("2024-04-10T15:00:00Z").getTime(), {
        in: tz("America/Los_Angeles"),
      }),
    ).toBe(true);
  });
});

